I think the fix could be simply to handle a disjoint ORR like an ADD:
```diff
diff --git a/llvm/lib/Target/AArch64/AArch64FrameLowering.cpp b/llvm/lib/Target/AArch64/AArch64FrameLowering.cpp
index c22dbb9bf006..8b41cdb80424 100644
--- a/llvm/lib/Target/AArch64/AArch64FrameLowering.cpp
+++ b/llvm/lib/Target/AArch64/AArch64FrameLowering.cpp
@@ -401,8 +401,9 @@ static unsigned estimateRSStackSizeLimit(MachineFunction &MF) {
   for (MachineBasicBlock &MBB : MF) {
     for (MachineInstr &MI : MBB) {
       if (MI.isDebugInstr() || MI.isPseudo() ||
-          MI.getOpcode() == AArch64::ADDXri ||
-          MI.getOpcode() == AArch64::ADDSXri)
+          llvm::is_contained(
+              {AArch64::ADDXri, AArch64::ADDSXri, AArch64::ORRXri},
+              MI.getOpcode()))
         continue;

       for (const MachineOperand &MO : MI.operands()) {
diff --git a/llvm/lib/Target/AArch64/AArch64InstrInfo.cpp b/llvm/lib/Target/AArch64/AArch64InstrInfo.cpp
index d1e0d37e33e4..a0dd3d7c050a 100644
--- a/llvm/lib/Target/AArch64/AArch64InstrInfo.cpp
+++ b/llvm/lib/Target/AArch64/AArch64InstrInfo.cpp
@@ -6343,7 +6343,8 @@ bool llvm::rewriteAArch64FrameIndex(MachineInstr &MI, unsigned FrameRegIdx,
   unsigned Opcode = MI.getOpcode();
   unsigned ImmIdx = FrameRegIdx + 1;

-  if (Opcode == AArch64::ADDSXri || Opcode == AArch64::ADDXri) {
+  if (Opcode == AArch64::ADDSXri || Opcode == AArch64::ADDXri ||
+      (Opcode == AArch64::ORRXri && MI.getFlag(MachineInstr::Disjoint))) {
     Offset += StackOffset::getFixed(MI.getOperand(ImmIdx).getImm());
     emitFrameOffset(*MI.getParent(), MI, MI.getDebugLoc(),
                     MI.getOperand(0).getReg(), FrameReg, Offset, TII,
```

